package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.support.TransactionSynchronizationManager;import java.util.*;import java.math.BigInteger;import java.time.*;import com.ruoyi.medical.identity.ServiceCertificateIdentity;import jakarta.servlet.http.HttpServletRequest;
/** Actual dispatch CAS/state logic with SQL and already-authenticated proof fixtures. No network or DB integration claim. */
class FormalInvocationDispatchTest {
 JdbcTemplate db;FormalInvocationSchema schema;FormalInvocationDispatch dispatch;ServiceCertificateIdentity services;ServiceCertificateIdentity.Verified service;EnterpriseAccess.Admission a;RunTokenAuthority.Admission w;FormalInvocationSendPreparation.Prepared prepared;HttpServletRequest http;TenantScope scope;FormalVerificationJobs.Job job;String tenant=id(1),actor=id(2),invocation=id(3),hash="a".repeat(64),stored,status="RESERVED",generation="0",lease="1";boolean attempt;
 @BeforeEach void setup()throws Exception{TransactionSynchronizationManager.setActualTransactionActive(true);scope=TenantScope.open(new TenantScope.Identity(tenant,actor,BigInteger.ZERO,BigInteger.ONE,BigInteger.ONE));db=mock(JdbcTemplate.class);schema=new FormalInvocationSchema();services=mock(ServiceCertificateIdentity.class);service=mock(ServiceCertificateIdentity.Verified.class);http=mock(HttpServletRequest.class);when(services.require(http)).thenReturn(service);when(service.serviceUri()).thenReturn("spiffe://test/gateway");when(service.certificateSha256()).thenReturn(hash);when(service.trustRevision()).thenReturn(id(22));a=mock(EnterpriseAccess.Admission.class);when(a.actorId()).thenReturn(actor);w=mock(RunTokenAuthority.Admission.class);when(w.initiatorId()).thenReturn(actor);when(w.serviceUri()).thenReturn("spiffe://test/gateway");when(w.leaseGeneration()).thenReturn(BigInteger.ONE);
  job=new FormalVerificationJobs.Job(tenant,id(4),id(5),id(6),actor,"original-key-000000",id(7),id(8),id(9),id(10),id(11),id(12),id(13),id(14),id(15),"{}",hash,hash,"{}",hash,schema.manifestSha256(),LocalDateTime.now(ZoneOffset.UTC),"INTERNAL");prepared=mock(FormalInvocationSendPreparation.Prepared.class);when(prepared.job()).thenReturn(job);when(prepared.providerBody()).thenReturn(schema.parse("{\"model\":\"fixed\"}"));String bodyHash=schema.hash(prepared.providerBody());when(prepared.canonicalProviderBodySha256()).thenReturn(bodyHash);dispatch=new FormalInvocationDispatch(db,services,schema,60);
  when(db.query(anyString(),any(RowMapper.class),any(Object[].class))).thenAnswer(call->{String sql=call.getArgument(0);if(sql.startsWith("SELECT status")){var type=Class.forName(FormalInvocationDispatch.class.getName()+"$Row");var c=type.getDeclaredConstructors()[0];c.setAccessible(true);return List.of(c.newInstance(status,generation,lease,id(16),"credential-revision",stored,stored==null?null:schema.hash(schema.parse(stored))));}if(sql.contains("FROM formal_invocation_attempt"))return attempt?List.of(id(17)):List.of();if(sql.contains("SELECT lease_expires_at"))return List.of(LocalDateTime.now(ZoneOffset.UTC).plusMinutes(5));if(sql.contains("SELECT actual_send_manifest"))return List.of(stored);throw new AssertionError(sql);});when(db.query(eq("SELECT UTC_TIMESTAMP(6)"),any(RowMapper.class))).thenReturn(List.of(LocalDateTime.now(ZoneOffset.UTC)));when(db.update(anyString(),any(Object[].class))).thenAnswer(call->{if(((String)call.getArgument(0)).startsWith("UPDATE invocation"))stored=call.getArgument(1);return 1;});
 }
 @AfterEach void close(){scope.close();TransactionSynchronizationManager.clear();}
 @Test void actualFirstCasCreatesSingleUsePostCommitPermit()throws Exception{var permit=dispatch.begin(http,a,w,invocation,prepared).orElseThrow();assertThrows(TenantAccessException.class,permit::claimProviderBody);TransactionSynchronizationManager.setActualTransactionActive(false);assertEquals(prepared.providerBody(),permit.claimProviderBody());assertThrows(TenantAccessException.class,permit::claimProviderBody);assertNotNull(permit.attemptId());}
 @Test void oldAttemptNeverReturnsAnotherPermit()throws Exception{attempt=true;status="DISPATCHING";generation="1";stored="{}";assertTrue(dispatch.begin(http,a,w,invocation,prepared).isEmpty());verify(db,never()).update(anyString(),any(Object[].class));}
 @Test void rolledBackMutableStatusCannotIgnoreImmutableAttempt(){attempt=true;assertThrows(TenantAccessException.class,()->dispatch.begin(http,a,w,invocation,prepared));verify(db,never()).update(anyString(),any(Object[].class));}
 @Test void removedAttemptCannotReopenDispatchedState(){status="DISPATCHING";generation="1";stored="{}";assertThrows(TenantAccessException.class,()->dispatch.begin(http,a,w,invocation,prepared));}
 @Test void leaseChangeDoesNotTransferOldReservation(){lease="2";assertThrows(TenantAccessException.class,()->dispatch.begin(http,a,w,invocation,prepared));}
 @Test void wrongActualServiceCannotDispatch(){when(service.serviceUri()).thenReturn("spiffe://test/other");assertThrows(TenantAccessException.class,()->dispatch.begin(http,a,w,invocation,prepared));verify(db,never()).update(anyString(),any(Object[].class));}
 static String id(int n){return "00000000-0000-4000-8000-"+String.format("%012d",n);}
}
